private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int b = bb.get(i) & 0xFF;
    if (b < 0x80) {
        sb.append((char) b);
        return i + 1;
    } else if (b < 0xC0) {
        // Unexpected continuation byte
        sb.append('\uFFFD');
        return i + 1;
    } else if (b < 0xE0) {
        // 2-byte sequence
        if (i + 1 >= bb.limit()) {
            sb.append('\uFFFD');
            return i + 1;
        }
        int b2 = bb.get(i + 1) & 0xFF;
        if ((b2 & 0xC0) != 0x80) {
            sb.append('\uFFFD');
            return i + 1;
        }
        int codePoint = ((b & 0x1F) << 6) | (b2 & 0x3F);
        sb.append((char) codePoint);
        return i + 2;
    } else if (b < 0xF0) {
        // 3-byte sequence
        if (i + 2 >= bb.limit()) {
            sb.append('\uFFFD');
            return i + 1;
        }
        int b2 = bb.get(i + 1) & 0xFF;
        int b3 = bb.get(i + 2) & 0xFF;
        if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
            sb.append('\uFFFD');
            return i + 1;
        }
        int codePoint = ((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
        sb.append((char) codePoint);
        return i + 3;
    } else if (b < 0xF8) {
        // 4-byte sequence
        if (i + 3 >= bb.limit()) {
            sb.append('\uFFFD');
            return i + 1;
        }
        int b2 = bb.get(i + 1) & 0xFF;
        int b3 = bb.get(i + 2) & 0xFF;
        int b4 = bb.get(i + 3) & 0xFF;
        if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80 || (b4 & 0xC0) != 0x80) {
            sb.append('\uFFFD');
            return i + 1;
        }
        int codePoint = ((b & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F);
        if (codePoint > 0x10FFFF) {
            sb.append('\uFFFD');
            return i + 1;
        }
        if (Character.isSurrogate(codePoint)) {
            sb.append('\uFFFD');
            return i + 1;
        }
        if (codePoint <= 0xFFFF) {
            sb.append((char) codePoint);
        } else {
            int high = 0xD800 + ((codePoint - 0x10000) >> 10);
            int low = 0xDC00 + ((codePoint - 0x10000) & 0x3FF);
            sb.append((char) high);
            sb.append((char) low);
        }
        return i + 4;
    } else {
        // Invalid leading byte
        sb.append('\uFFFD');
        return i + 1;
    }
}
