        throw new IllegalArgumentException("Size must be non-negative: " + size);
    }
    if (size == 0) {
        return;
    }
    int newSize = this.size + size;
    if (newSize < 0) {
        throw new IllegalArgumentException("New size would be negative: " + newSize);
    }
    byte[] newBuffer = new byte[newSize];
