private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null) {
        throw new IllegalArgumentException("headerPart must not be null");
    }
    if (end < 0 || end >= headerPart.length()) {
        throw new IndexOutOfBoundsException("end index out of bounds: " + end);
    }

    int i = end;
    while (i >= 0) {
        char c = headerPart.charAt(i);
        if (c == '\n') {
            // Check if preceded by \r
            if (i > 0 && headerPart.charAt(i - 1) == '\r') {
                return i - 1;
            } else {
                return i;
            }
        }
        i--;
    }

    // If no line ending found, return -1 or throw exception
    return -1;
}
