    @Override
    public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
        // Get the number of vertices in each partition
        int n = (int) parameters.getOrDefault("n", 3);
        int m = (int) parameters.getOrDefault("m", 3);

        // Validate parameters
        if (n < 0 || m < 0) {
            throw new IllegalArgumentException("Partition sizes must be non-negative");
        }

        // Create vertices for the first partition
        for (int i = 0; i < n; i++) {
            String key = "A" + i;
            V vertex = createVertex(key);
            target.addVertex(vertex);
            resultMap.put(key, vertex);
        }

        // Create vertices for the second partition
        for (int j = 0; j < m; j++) {
            String key = "B" + j;
            V vertex = createVertex(key);
            target.addVertex(vertex);
            resultMap.put(key, vertex);
        }

        // Add edges between every vertex in the first partition and every vertex in the second partition
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                V v1 = resultMap.get("A" + i);
                V v2 = resultMap.get("B" + j);
                E edge = createEdge(v1, v2);
                target.addEdge(v1, v2, edge);
            }
        }
    }
