void insertBefore(Bucket bucket) {
    if (bucket == null) {
        throw new IllegalArgumentException("Bucket cannot be null");
    }
    if (bucket.prev == null) {
        // bucket is the head, so this becomes the new head
        this.next = bucket;
        this.prev = null;
        bucket.prev = this;
    } else {
        // Insert between bucket.prev and bucket
        this.prev = bucket.prev;
        this.next = bucket;
        bucket.prev.next = this;
        bucket.prev = this;
    }
}
