    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        List<PathSegmentImpl> segments = new ArrayList<>();
        if (u == null) {
            return segments;
        }
        String path = u.getPath();
        if (path == null || path.isEmpty()) {
            return segments;
        }
        // If the path is an absolute path, ignore the leading '/'
        if (path.startsWith("/")) {
            path = path.substring(1);
        }
        if (path.isEmpty()) {
            return segments;
        }
        String[] parts = path.split("/", -1);
        for (String part : parts) {
            if (part.isEmpty()) {
                continue;
            }
            String decodedPart = part;
            if (decode) {
                try {
                    decodedPart = URLDecoder.decode(part, "UTF-8");
                } catch (UnsupportedEncodingException e) {
                    // UTF-8 is always supported, so this should not happen
                    decodedPart = part;
                }
            }
            segments.add(new PathSegmentImpl(decodedPart));
        }
        return segments;
    }
