public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    int len = str.length();
    if (len == 0) {
        return str;
    }
    StringBuilder buf = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i + 1 >= len) {
                buf.append(ch);
                continue;
            }
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    buf.append('\b');
                    i++;
                    break;
                case 't':
                    buf.append('\t');
                    i++;
                    break;
                case 'n':
                    buf.append('\n');
                    i++;
                    break;
                case 'f':
                    buf.append('\f');
                    i++;
                    break;
                case 'r':
                    buf.append('\r');
                    i++;
                    break;
                case 'u':
                    if (i + 5 >= len) {
                        throw new IllegalArgumentException("Invalid Unicode escape sequence");
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int codePoint = Integer.parseInt(hex, 16);
                        buf.append((char) codePoint);
                        i += 5;
                    } catch (NumberFormatException e) {
                        throw new IllegalArgumentException("Invalid Unicode escape sequence", e);
                    }
                    break;
                case '"':
                    buf.append('"');
                    i++;
                    break;
                case '\'':
                    buf.append('\'');
                    i++;
                    break;
                case '\\':
                    buf.append('\\');
                    i++;
                    break;
                default:
                    buf.append(ch);
                    break;
            }
        } else {
            buf.append(ch);
        }
    }
    return buf.toString();
}
