final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    try {
        // Read the length of the UTF-8 string
        int length = readUnsignedShort();

        // Read the modified UTF-8 bytes
        int offset = classFileBuffer.position();
        byte[] bytes = new byte[length];
        classFileBuffer.get(bytes);

        // Decode the modified UTF-8 bytes into characters
        int charCount = 0;
        int i = 0;
        while (i < length) {
            int b1 = bytes[i] & 0xFF;
            if (b1 == 0) {
                // Null character
                charBuffer[charCount++] = '\0';
                i++;
            } else if ((b1 & 0x80) == 0) {
                // Single-byte character
                charBuffer[charCount++] = (char) b1;
                i++;
            } else if ((b1 & 0xE0) == 0xC0) {
                // Two-byte character
                if (i + 1 >= length) {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding");
                }
                int b2 = bytes[i + 1] & 0xFF;
                if ((b2 & 0xC0) != 0x80) {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding");
                }
                charBuffer[charCount++] = (char) (((b1 & 0x1F) << 6) | (b2 & 0x3F));
                i += 2;
            } else if ((b1 & 0xF0) == 0xE0) {
                // Three-byte character
                if (i + 2 >= length) {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding");
                }
                int b2 = bytes[i + 1] & 0xFF;
                int b3 = bytes[i + 2] & 0xFF;
                if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding");
                }
                charBuffer[charCount++] = (char) (((b1 & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F));
                i += 3;
            } else {
                throw new IllegalArgumentException("Invalid UTF-8 encoding");
            }
        }

        return new String(charBuffer, 0, charCount);
    } catch (Exception e) {
        throw new RuntimeException("Error reading UTF-8 constant pool entry", e);
    }
}
