    int addConstantNameAndType(final String name, final String descriptor) {
        if (name == null || descriptor == null) {
            throw new IllegalArgumentException("Name and descriptor must not be null");
        }

        // Check if a similar item already exists in the constant pool
        for (int i = 0; i < constantPool.size(); i++) {
            Constant c = constantPool.get(i);
            if (c instanceof ConstantNameAndType) {
                ConstantNameAndType nat = (ConstantNameAndType) c;
                if (nat.name.equals(name) && nat.descriptor.equals(descriptor)) {
                    return i + 1; // Return the existing index (1-based)
                }
            }
        }

        // Create a new ConstantNameAndType and add it to the constant pool
        ConstantNameAndType nat = new ConstantNameAndType(name, descriptor);
        constantPool.add(nat);
        return constantPool.size(); // Return the new index (1-based)
    }
