private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null) {
        throw new IllegalArgumentException("bounds list cannot be null");
    }

    int n = bounds.size();
    List<Integer> suffixSum = new ArrayList<>(n);
    long totalSum = 0;

    // Compute total sum
    for (int i = 0; i < n; i++) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("bounds list contains null element at index " + i);
        }
        totalSum += val;
    }

    // Compute suffix sum from right to left
    long runningSum = 0;
    for (int i = n - 1; i >= 0; i--) {
        runningSum += bounds.get(i);
        suffixSum.add(0, (int) runningSum);
    }

    return new Pair<>(suffixSum, totalSum);
}
