private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new IllegalArgumentException("list must not be null");
    }
    if (list == this) {
        return;
    }
    ListNode<E> node = list.head;
    while (node != null) {
        ListNode<E> next = node.next;
        // Remove from list
        if (node.prev != null) {
            node.prev.next = node.next;
        } else {
            list.head = node.next;
        }
        if (node.next != null) {
            node.next.prev = node.prev;
        } else {
            list.tail = node.prev;
        }
        node.prev = null;
        node.next = null;
        list.size--;
        // Add to this list
        if (this.head == null) {
            this.head = node;
            this.tail = node;
        } else {
            node.prev = this.tail;
            this.tail.next = node;
            this.tail = node;
        }
        this.size++;
        node = next;
    }
}
