private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return lowerBounds;
    }
    for (K key : keys) {
        // Assuming K is comparable or has a way to determine a lower bound
        // For simplicity, we'll assume K is an Integer or can be converted to an Integer
        try {
            if (key instanceof Integer) {
                lowerBounds.add((Integer) key);
            } else if (key instanceof Number) {
                lowerBounds.add(((Number) key).intValue());
            } else {
                // Default to 0 if the key type is not numeric
                lowerBounds.add(0);
            }
        } catch (Exception e) {
            lowerBounds.add(0);
        }
    }
    return lowerBounds;
}
