private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor must not be null");
    }

    int count = 0;
    int i = 0;
    int len = descriptor.length();

    // If it's a method descriptor, skip the opening parenthesis
    if (i < len && descriptor.charAt(i) == '(') {
        i++;
        // Parse argument types
        while (i < len && descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            if (c == 'L') {
                // Object type, find the closing semicolon
                int end = descriptor.indexOf(';', i);
                if (end == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: missing semicolon");
                }
                i = end + 1;
                count++;
            } else if (c == '[') {
                // Array type, skip all leading brackets
                while (i < len && descriptor.charAt(i) == '[') {
                    i++;
                }
                // Now parse the component type
                if (i < len) {
                    char component = descriptor.charAt(i);
                    if (component == 'L') {
                        int end = descriptor.indexOf(';', i);
                        if (end == -1) {
                            throw new IllegalArgumentException("Invalid descriptor: missing semicolon");
                        }
                        i = end + 1;
                    } else {
                        i++;
                    }
                }
                count++;
            } else {
                // Primitive type
                i++;
                count++;
            }
        }
        // Skip the closing parenthesis
        if (i < len && descriptor.charAt(i) == ')') {
            i++;
        }
        // Now parse the return type (but we don't pop it, only argument types)
        // The method descriptor's argument types are what we need to pop
    } else {
        // It's a type descriptor, pop one type
        count = 1;
    }

    // Pop the types from the output frame stack
    for (int j = 0; j < count; j++) {
        if (outputFrameStack.isEmpty()) {
            throw new IllegalStateException("Output frame stack is empty, cannot pop " + count + " types");
        }
        outputFrameStack.pop();
    }
}

