public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path cannot be null");
    }

    // Normalize the base path: ensure it ends with a separator if it's a directory
    String normalizedPath = path;
    if (!normalizedPath.endsWith("/") && !normalizedPath.endsWith("\\")) {
        // Check if the path looks like a file (has an extension) or is a directory
        // For simplicity, we'll treat it as a directory if it doesn't have a file extension
        // But actually, the standard approach is to just append with a separator
        // Let's use a more robust approach:
        // If the path doesn't end with a separator, we need to add one before appending
        // But we should be careful not to add a separator if the path is empty or just a drive letter
        if (normalizedPath.length() > 0) {
            // Check if it's a Windows drive letter like "C:"
            if (normalizedPath.length() == 2 && normalizedPath.charAt(1) == ':') {
                normalizedPath = normalizedPath + "/";
            } else {
                normalizedPath = normalizedPath + "/";
            }
        }
    }

    // Remove leading separator from relative path if present
    String cleanedRelative = relativePath;
    while (cleanedRelative.startsWith("/") || cleanedRelative.startsWith("\\")) {
        cleanedRelative = cleanedRelative.substring(1);
    }

    // If relative path is empty, return the normalized path
    if (cleanedRelative.isEmpty()) {
        return normalizedPath;
    }

    // Combine the paths
    String result = normalizedPath + cleanedRelative;

    // Normalize the result: handle ".." and "." segments
    String[] parts = result.split("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();

    for (String part : parts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pop();
            }
        } else {
            stack.push(part);
        }
    }

    // Reconstruct the path
    StringBuilder sb = new StringBuilder();
    // Check if the original path was absolute
    boolean isAbsolute = path.startsWith("/") || path.startsWith("\\") || (path.length() >= 2 && path.charAt(1) == ':');

    if (isAbsolute) {
        if (path.length() >= 2 && path.charAt(1) == ':') {
            // Windows absolute path
            sb.append(path.substring(0, 2));
        } else {
            sb.append("/");
        }
    }

    // The stack is in reverse order, so we need to reverse it
    java.util.List<String> reversed = new java.util.ArrayList<>();
    while (!stack.isEmpty()) {
        reversed.add(stack.pop());
    }

    for (int i = 0; i < reversed.size(); i++) {
        if (i > 0) {
            sb.append("/");
        }
        sb.append(reversed.get(i));
    }

    // If the result is empty and the path was absolute, return the root
    if (sb.length() == 0) {
        if (isAbsolute) {
            if (path.length() >= 2 && path.charAt(1) == ':') {
                return path.substring(0, 2) + "/";
            } else {
                return "/";
            }
        } else {
            return "";
        }
    }

    return sb.toString();
}
