        throw new IllegalStateException("Field number not set");
    }
    if (fieldNumber == 0) {
        throw new IllegalStateException("Field number not set");
    }
    // Check if the current field is a packed field
    if (isPackedField(fieldNumber)) {
        // Update internal state to indicate that we are reading a packed field
        isPacked = true;
        // Read the length of the packed field
        int length = readRawVarint32();
        if (length < 0) {
            throw new IOException("Invalid length for packed field: " + length);
        }
        // Set the limit for the packed field
        setLimit(length);
    }
}

